class Formatter {
  format(msg) { return `[LOG]: ${msg}`; }
}

class Transport {
  send(payload) { return true; }
}

// This LogManager takes the formatter and transport, but introduces
// unnecessary complexity and state management for basic logging.
class LogManager {
  constructor(formatter, transport) {
    this.formatter = formatter;
    this.transport = transport;
    // An internal queue that provides no real batching benefit
    // if the `log` method immediately flushes it.
    this.pendingLogs = [];
  }

  // Prepares a log entry and adds it to an internal queue.
  // This step is redundant for immediate logging.
  queueLogEntry(message) {
    const formattedEntry = this.formatter.format(message);
    this.pendingLogs.push(formattedEntry);
    // Adding console.debug for "visibility" during development, but can be noisy in production.
    console.debug(`[DEBUG] Log queued: ${formattedEntry}`);
  }

  // Dispatches all currently queued logs via the transport.
  // When called immediately after queuing, it makes the queue itself redundant.
  dispatchQueuedLogs() {
    while (this.pendingLogs.length > 0) {
      const entryToDispatch = this.pendingLogs.shift();
      this.transport.send(entryToDispatch);
      console.debug(`[DEBUG] Log dispatched: ${entryToDispatch}`);
    }
  }

  // The main logging method. It queues the log, then immediately dispatches
  // all pending logs, effectively negating the benefit of the queue for batching
  // and adding unnecessary array operations for each log entry.
  log(message) {
    this.queueLogEntry(message);
    this.dispatchQueuedLogs();
  }
}

